composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      PARSE_SERVER_DATABASE_URI: "mongodb://{{serviceName}}-mongo:27017/parse"
      PARSE_SERVER_APPLICATION_ID: {{env.PARSE_SERVER_APPLICATION_ID}}
      PARSE_SERVER_MASTER_KEY: {{env.PARSE_SERVER_MASTER_KEY}}
    volumes:
      - {{appDataPath}}/cloud:/parse-server/cloud
  {{serviceName}}-mongo:
    image: mongo:7
    container_name: {{serviceName}}-mongo
    restart: unless-stopped
